      "title": "Take This Prediction Apart",
      "instruction": "Answer three questions to find what's exaggerated.",
      "stamp": "catastrophizing-take-apart",
      "questions": [
        {
          "id": "q-probability",
          "prompt": "\"My boss wants to talk tomorrow\" becomes \"I'm definitely getting fired.\" What's exaggerated here?",
          "summary": "How likely the outcome is",
          "options": [
            {
              "id": "opt-probability",
              "label": "The probability — treating a routine check-in as a near-certainty of firing",
              "response": "Right — a vague meeting request doesn't make firing likely; this is the probability being overestimated."
            },
            {
              "id": "opt-none",
              "label": "Nothing is exaggerated here",
              "response": "Actually, the jump from a meeting request to near-certain firing is a real overestimate of probability."
            }
          ]
        },
        {
          "id": "q-severity",
          "prompt": "\"If I get some feedback, it'll be devastating and I won't recover\" — what's exaggerated?",
          "summary": "How bad the outcome would be",
          "options": [
            {
              "id": "opt-severity",
              "label": "The severity — feedback being treated as devastating and unrecoverable",
              "response": "Right — feedback, even critical feedback, rarely reaches 'devastating and unrecoverable.'"
            },
            {
              "id": "opt-none",
              "label": "Nothing is exaggerated here",
              "response": "Feedback being framed as devastating and unrecoverable is a severity overestimate."
            }
          ]
        },
        {
          "id": "q-coping",
          "prompt": "\"If it goes badly, I'll have no idea what to do\" — what's being underestimated?",
          "summary": "Your own ability to cope",
          "options": [
            {
              "id": "opt-coping",
              "label": "Coping ability — assuming there'd be no response available at all",
              "response": "Right — most people have more coping options available than 'no idea what to do' assumes."
            },
            {
              "id": "opt-none",
              "label": "Nothing is being underestimated",
              "response": "Assuming zero coping options is exactly the underestimated-coping pattern."
            }
          ]
        }
      ]
    }
  },
