        {
          "concept": "Catastrophizing",
          "prompt": "What three things can catastrophizing overestimate or underestimate?",
          "clue": "Probability, severity, coping.",
          "worked": "Overestimated probability, overestimated severity, underestimated coping ability.",
          "options": [
            {
              "label": "Probability, severity, and coping",
              "feedback": "Right.",
              "isCorrect": true
            },
            {
              "label": "Only probability",
              "feedback": "It can also overestimate severity and underestimate coping.",
              "isCorrect": false
            }
          ]
        },
        {
          "concept": "Safety Behaviors",
          "prompt": "What does a safety behavior prevent?",
          "clue": "The fear being tested.",
          "worked": "It prevents the feared outcome from ever being tested and disconfirmed.",
          "options": [
