            }
          ]
        },
        {
          "concept": "Avoidance Cycle",
          "prompt": "Does avoiding something anxious have an effect on next time?",
          "clue": "Relief now, louder later.",
          "worked": "Yes — relief now, and a louder alarm next time.",
